// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!doctype html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>X • O</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:radial-gradient(circle at 50% 0,#17224a,#070b18 70%);color:#e8f0ff;font-family:system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-user-select:none;user-select:none}\nbody{display:flex;justify-content:center;padding:10px}\n.wrap{width:100%;max-width:460px;text-align:center}\nh1{margin:6px 0 8px;font-size:24px;letter-spacing:.5px}\n.hud{display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:15px}\n.hud span{flex:1;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;padding:6px 8px}\ncanvas{display:block;margin:0 auto;width:100%;height:auto;border-radius:14px;border:2px solid #4cc9f0;background:#0a1128;touch-action:none;box-shadow:0 0 24px #4cc9f044}\nbutton{font:inherit;color:#fff;background:linear-gradient(#3a86ff,#2563eb);border:0;border-radius:12px;padding:10px 16px;cursor:pointer;box-shadow:0 3px 0 #1b3f9a}\nbutton:active{transform:translateY(2px);box-shadow:none}\n.row{display:flex;gap:8px;justify-content:center;margin:10px 0;flex-wrap:wrap}\n.hint{opacity:.7;font-size:13px;margin:6px 0}\n.msg{min-height:24px;font-weight:700;color:#ffd166;margin:6px 0}\n.board{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px auto;max-width:340px}\n.cell{aspect-ratio:1;font-size:clamp(40px,14vw,64px);font-weight:800;padding:0;background:#16204a;box-shadow:0 3px 0 #0a1230;border:2px solid #2c3d7a;color:#fff}\n.cell.x{color:#4cc9f0}.cell.o{color:#ff6b9d}\n.cell.w{background:#2d6a4f;border-color:#7ae582}\n.seg button{background:#16204a;box-shadow:none;border:2px solid #2c3d7a;padding:6px 14px}\n.seg button.on{background:#3a86ff;border-color:#9ec1ff}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<h1>❌⭕ X • O</h1>\n<div class=\"hud\"><span>Sən (X): <b id=\"sx\">0</b></span><span>Bərabər: <b id=\"sd\">0</b></span><span>Kompüter (O): <b id=\"so\">0</b></span></div>\n<div class=\"row seg\"><button data-l=\"easy\">Asan</button><button data-l=\"hard\" class=\"on\">Çətin</button></div>\n<div class=\"board\" id=\"bd\"></div>\n<div class=\"msg\" id=\"msg\"></div>\n<div class=\"row\"><button id=\"re\">Yeni oyun</button></div>\n<p class=\"hint\">Xanaya toxun və ya kliklə. Kompüter ağıllı oynayır!</p>\n</div>\n<script>\nconst LINES = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nconst $ = id => document.getElementById(id);\nlet gid = 0, b, over, level = 'hard', starter = 'X', busy = false, wins = { X: 0, O: 0, D: 0 };\nconst cells = [];\nfor (let i = 0; i < 9; i++) {\n  const c = document.createElement('button'); c.className = 'cell'; c.setAttribute('aria-label', 'Xana ' + (i + 1));\n  c.onclick = () => play(i); $('bd').appendChild(c); cells.push(c);\n}\nfunction winner(bd) { for (const l of LINES) if (bd[l[0]] && bd[l[0]] === bd[l[1]] && bd[l[0]] === bd[l[2]]) return l; return null; }\nfunction minimax(bd, isO, depth) {\n  const w = winner(bd);\n  if (w) return bd[w[0]] === 'O' ? 10 - depth : depth - 10;\n  if (bd.every(Boolean)) return 0;\n  let best = isO ? -99 : 99;\n  for (let i = 0; i < 9; i++) if (!bd[i]) {\n    bd[i] = isO ? 'O' : 'X';\n    const v = minimax(bd, !isO, depth + 1);\n    bd[i] = '';\n    best = isO ? Math.max(best, v) : Math.min(best, v);\n  }\n  return best;\n}\nfunction aiMove() {\n  const free = []; for (let i = 0; i < 9; i++) if (!b[i]) free.push(i);\n  if (level === 'easy' && Math.random() < 0.6) return free[Math.random() * free.length | 0];\n  let bi = free[0], bv = -99;\n  for (const i of free) {\n    b[i] = 'O'; const v = minimax(b, false, 1); b[i] = '';\n    if (v > bv || (v === bv && Math.random() < 0.3)) { bv = v; bi = i; }\n  }\n  return bi;\n}\nfunction render() {\n  cells.forEach((c, i) => { c.textContent = b[i]; c.className = 'cell ' + b[i].toLowerCase(); });\n}\nfunction finish() {\n  const w = winner(b);\n  if (w) {\n    over = true; const who = b[w[0]]; wins[who]++;\n    w.forEach(i => cells[i].classList.add('w'));\n    $('msg').textContent = who === 'X' ? 'Təbrik edirik, qazandın! 🎉' : 'Kompüter qazandı 🤖';\n  } else if (b.every(Boolean)) { over = true; wins.D++; $('msg').textContent = 'Bərabərlik 🤝'; }\n  $('sx').textContent = wins.X; $('sd').textContent = wins.D; $('so').textContent = wins.O;\n  return over;\n}\nfunction play(i) {\n  if (over || busy || b[i]) return;\n  b[i] = 'X'; render();\n  if (finish()) return;\n  busy = true; $('msg').textContent = 'Kompüter düşünür…';\n  const g = gid;\n  setTimeout(() => { if (g !== gid) return; b[aiMove()] = 'O'; busy = false; $('msg').textContent = ''; render(); finish(); }, 350);\n}\nfunction reset() {\n  gid++; b = Array(9).fill(''); over = false; busy = false; $('msg').textContent = '';\n  starter = starter === 'X' ? 'O' : 'X'; render();\n  if (starter === 'O') { busy = true; const g = gid; setTimeout(() => { if (g !== gid) return; b[aiMove()] = 'O'; busy = false; render(); }, 350); }\n}\ndocument.querySelectorAll('.seg button').forEach(s => s.onclick = () => {\n  level = s.dataset.l; document.querySelectorAll('.seg button').forEach(o => o.classList.toggle('on', o === s));\n  starter = 'O'; reset();\n});\n$('re').onclick = reset;\nstarter = 'O'; reset();\n\n</script>\n</body>\n</html>\n";
